from django.db import migrations, models


def record_current_wording(apps, schema_editor):
    """Give every existing result the wording its assessment has today.

    What a respondent actually saw before snapshots existed was never kept, so
    today's wording is the best record there is. From here on, editing an
    assessment no longer changes what these results say was asked.
    """
    Response = apps.get_model("assessments", "AssessmentResponse")
    Question = apps.get_model("assessments", "AssessmentQuestion")
    by_assessment = {}
    for response in Response.objects.filter(question_snapshot=[]).iterator():
        if response.assessment_id not in by_assessment:
            by_assessment[response.assessment_id] = [
                {"identifier": q.identifier, "order": q.order, "text": q.text,
                 "response_type": q.response_type, "config": q.config if isinstance(q.config, dict) else {}}
                for q in Question.objects.filter(assessment_id=response.assessment_id).order_by("order")
            ]
        response.question_snapshot = by_assessment[response.assessment_id]
        response.save(update_fields=["question_snapshot"])


